import React, { useEffect, useRef, useState } from "react";
import { useSearchParams, useNavigate } from "react-router-dom";
import { useUI } from "../context/UIContext";
import Button from "../components/common/Button";
import Card from "../components/common/Card";
import styles from "../SDM.module.css";
import eveVideo from "../assets/eve_sdm_talk.mp4";
import { topicDescriptions } from "../constants/sdm";

const SDM = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const navigate = useNavigate();
  const { setHeroData, allAnswers } = useUI();
  const videoRef = useRef(null);

  const step = searchParams.get("step") || "SELECT";
  const selectedTopicId = searchParams.get("topic");

  const [isPlaying, setIsPlaying] = useState(false); // 僅控制語音狀態
  const [currentSubtitle, setCurrentSubtitle] = useState("");

  // 1. 影片邏輯：載入即循環播放，永不暫停
  useEffect(() => {
    setHeroData(null);
    if (videoRef.current) {
      videoRef.current.muted = true; // 確保不發出聲音
      videoRef.current.play().catch((e) => console.log("Video play error:", e));
    }
  }, [setHeroData]);

  // 2. 語音邏輯：獨立於影片
  const handlePlaySpeech = (text) => {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = "zh-TW";

    utterance.onstart = () => setIsPlaying(true);
    utterance.onend = () => setIsPlaying(false);

    // 字幕同步
    const sentences = text.match(/[^。？！，、]+[。？！，、]?/g) || [text];
    utterance.onboundary = (e) => {
      let charCount = 0;
      for (const s of sentences) {
        if (e.charIndex >= charCount && e.charIndex < charCount + s.length) {
          setCurrentSubtitle(s);
          break;
        }
        charCount += s.length;
      }
    };

    window.speechSynthesis.speak(utterance);
  };

  // 3. 按鈕邏輯：只控制語音，不干涉影片
  const toggleSpeech = () => {
    if (window.speechSynthesis.speaking) {
      if (window.speechSynthesis.paused) {
        window.speechSynthesis.resume();
        setIsPlaying(true);
      } else {
        window.speechSynthesis.pause();
        setIsPlaying(false);
      }
    }
  };

  return (
    <div className={styles.pageContainer}>
      <div className={styles.interactiveCard}>
        <div className={styles.videoSection}>
          {/* 影片始終 loop，不受任何點擊影響 */}
          <video
            ref={videoRef}
            src={eveVideo}
            playsInline
            loop
            className={styles.theatreVideo}
          />
          {isPlaying && currentSubtitle && (
            <div className={styles.subtitleOverlay}>
              <p className={styles.subtitleText}>{currentSubtitle}</p>
            </div>
          )}
          <button className={styles.controlBtnTopRight} onClick={toggleSpeech}>
            {isPlaying ? "⏸ 暫停語音" : "▶️ 繼續語音"}
          </button>
        </div>

        <div className={styles.contentSection}>
          {step === "SELECT" ? (
            <>
              {Object.keys(topicDescriptions).map((key) => (
                <Card
                  key={key}
                  title={topicDescriptions[key].label}
                  description={topicDescriptions[key].description}
                  isActive={selectedTopicId === key}
                  onClick={() =>
                    setSearchParams({ step: "SELECT", topic: key })
                  }
                />
              ))}
              <Button
                onClick={() => {
                  const id = selectedTopicId;
                  if (id) {
                    setSearchParams({ step: "INTRO", topic: id });
                    handlePlaySpeech(
                      topicDescriptions[id].content.replace(/<[^>]+>/g, ""),
                    );
                  }
                }}
                fullWidth
                disabled={!selectedTopicId}
              >
                確認選擇並查看詳情 ➔
              </Button>
              <Button
                variant="outline"
                onClick={() => navigate("/selections")}
                fullWidth
              >
                返回方案選擇頁面
              </Button>
            </>
          ) : (
            <div>
              <div
                dangerouslySetInnerHTML={{
                  __html: topicDescriptions[selectedTopicId]?.content,
                }}
              />
              <Button
                variant="outline"
                onClick={() => {
                  window.speechSynthesis.cancel();
                  setSearchParams({ step: "SELECT" });
                }}
                fullWidth
              >
                返回選擇主題
              </Button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default SDM;
